def count_divisors(n):
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer.")
    if n == 0:
        raise ValueError("Input cannot be zero.")

    count = 0
    for d in range(1, int(n**0.5) + 1):
        if n % d == 0:
            if d * d == n:
                count += 1
            else:
                count += 2
    return count
